    fun text(semanticKey: String, dialect: ArabicDialect, fallback: String): String =
        if (dialect == ArabicDialect.STANDARD) fallback else words[semanticKey]?.get(dialect) ?: fallback

    fun localize(value: WordItem, dialect: ArabicDialect): WordItem {
        val item = value.forEditing()
        val key = item.semanticKey ?: return item
        if (dialect == ArabicDialect.STANDARD || item.categoryId.startsWith("custom_")) return item
        fun custom(flag: Int) = item.customTextFields and flag != 0
        val regional = RegionalDishesCatalog.variant(key, dialect)
        if (regional == null && key !in words) return item
        val visible = if (custom(CardDetails.LABEL)) item.displayText
            else regional?.displayText ?: text(key, dialect, item.displayText)
        val protectedSpeech = custom(CardDetails.SPEECH) || custom(CardDetails.LABEL)
        val speech = if (protectedSpeech) item.ttsPrompt else regional?.ttsPrompt
            ?: DialectSpeechCatalog.spoken(key, visible, item.ttsPrompt, dialect, item.displayText)
        return item.copy(
            displayText = visible, ttsPrompt = speech,
            phonemicCue = if (custom(CardDetails.CUE)) item.phonemicCue else regional?.phonemicCue
                ?: DialectSpeechCatalog.cue(key, speech, item.phonemicCue, dialect, protectedSpeech),
            sentencePrompt = if (custom(CardDetails.SENTENCE)) item.sentencePrompt
                else regional?.sentencePrompt ?: item.sentencePrompt,
            sourceDetails = CardDetails.from(item),
        )
    }
}
